package com.quincaisoft.expenses.application;import com.quincaisoft.finance.api.PeriodCloseGuard;import jakarta.persistence.EntityManager;import org.springframework.stereotype.Component;import java.time.LocalDate;
@Component public class ExpensePeriodGuard implements PeriodCloseGuard {private final EntityManager em;public ExpensePeriodGuard(EntityManager em){this.em=em;}public String domain(){return "expenses";}public void verifyCanClose(LocalDate start,LocalDate end){long n=em.createQuery("select count(r) from ExpenseEntity r where r.status in ('IN_REVIEW','APPROVED') and r.businessDate between :start and :end",Long.class).setParameter("start",start).setParameter("end",end).getSingleResult();if(n>0)throw new IllegalStateException("Unresolved approved/review expenses prevent period closure");}}
